 const row=x=>`<tr><td><b>${esc(moduleTitle(x.canonicalId,x.title))}</b><small>${esc(x.canonicalId)}</small></td><td>${recipeTargetsHtml(x.canonicalId,true)}</td><td>${badge(x.eligibility.ok?(x.eligibility.mode==="production"?"Déjà en service":"Testable sur ce navigateur"):x.eligibility.reason,x.eligibility.ok?"ok":"warn")}${!x.eligibility.ok?`<div><button class="ktm-btn ktm-small" data-recipe-manual="${esc(x.canonicalId)}">Préparer la recette manuelle</button></div>`:""}</td><td>${badge(recipeStateLabel(x.validation),recipeStateTone(x.validation))}${x.validation?.stale?`<small>La recette, le code ou la configuration a changé depuis la dernière validation.</small>`:""}</td></tr>`;
