 if(moduleView==="historical")return `<article class="ktm-module"><div class="ktm-row"><div><div class="ktm-module-domain">${esc(categoryLabel(x.m.category))}</div><h3>${esc(moduleTitle(x.cid,x.m.title))}</h3></div>${canaryActive?badge("TEST ACTIF SUR CE NAVIGATEUR","warn"):badge("MIGRATION À RECETTER","warn")}</div><p>${esc(moduleDescription(x.cid,x.m.description)||x.m.description||"")}</p><div class="ktm-module-targets"><b>Pages de test :</b> ${recipeTargetsHtml(x.cid,true)}</div><div class="ktm-module-tech"><b>Informations techniques :</b> ${esc(x.cid)} · ancien(s) script(s) ${esc(x.ms.map(y=>y.legacyFile).filter(Boolean).join(", ")||"—")} · candidate ${esc([...new Set(x.ms.map(y=>y.nextModule).filter(Boolean))].join(", ")||"—")}</div><div class="ktm-info">${x.elig.ok?"Le test charge la candidate uniquement pour votre compte et ce navigateur. Aucun autre poste n’est affecté.":`Test automatique indisponible : ${esc(x.elig.reason||"mapping non compatible")}.`}</div><div class="ktm-actions"><button class="ktm-btn ktm-primary" data-config-admin="${esc(x.cid)}">Configurer</button>${A()?.can?.("developer")&&x.elig.ok?`<button class="ktm-btn ${canaryActive?"ktm-warn":"ktm-success"}" data-canary="${esc(x.cid)}">${canaryActive?"Arrêter le test":"Tester sur ce navigateur"}</button>`:""}<button class="ktm-btn" data-validation="${esc(x.cid)}">État de validation</button></div></article>`;
