 if(typeof val==="number"){const unit=unitForKey(key);return `<label class="ktm-field ${changed?"is-changed":""}" data-config-field data-search="${blob}"><div class="ktm-field-head"><span>${esc(fieldLabel(key,path))}${chg}${originChip(path)}</span><small>${esc(help)}</small></div><div class="ktm-input-row"><input type="number" step="any" value="${esc(val)}" data-cfg-path='${p}' data-cfg-type="number">${unit?`<span class="ktm-unit">${esc(unit)}</span>`:""}${reset}</div></label>`}
