 return `<div class="ktm-object-group ${changed?"is-changed":""}" data-config-field data-search="${blob}"><div class="ktm-group-title"><div><span>${esc(fieldLabel(key,path))}</span><small>${esc(help)}</small></div>${badge(arr.length+" élément(s)")}</div><div class="ktm-collection-cards">${arr.map((item,i)=>`<details class="ktm-collection-item" ${i===0?"open":""}><summary><b>${esc(item?.label||item?.name||item?.id||("Élément "+(i+1)))}</b><button type="button" class="ktm-mini-danger" data-array-remove='${esc(JSON.stringify([...path,i]))}'>Supprimer</button></summary>${renderObjectEditor(item,[...path,i],Array.isArray(baseVal)?baseVal[i]:undefined,depth+1)}</details>`).join("")}</div><div class="ktm-actions"><button type="button" class="ktm-btn" data-array-add='${p}'>+ Ajouter un élément</button>${resetButton(path,changed)}</div></div>`;
