 <div class="ktm-config-viewbar"><div><b>${configAdminMode?"Configuration complète":"Réglages utiles au quotidien"}</b><small>${configAdminMode?"Les paramètres techniques restent disponibles ici pour la maintenance du module.":"Modifiez le fonctionnement ou l’apparence du module. Les paramètres techniques sont réservés à l’administration."}</small></div>${configAdminMode?`<div class="ktm-config-legend"><span>${badge("Courant","ok")}</span><span>${badge("Avancé","info")}</span></div>`:""}</div>
